function updateAudioButton() {
  if (!soundToggle) {
    return;
  }

  const label = soundToggle.querySelector(".sound-toggle-label");
  soundToggle.classList.toggle("is-on", audioEnabled);
  soundToggle.setAttribute("aria-pressed", String(audioEnabled));
  soundToggle.setAttribute("aria-label", textFor(audioEnabled ? "audio.turnOff" : "audio.turnOn"));
  if (label) {
    label.textContent = textFor(audioEnabled ? "audio.on" : "audio.off");
  }
}

function ensureAudioContext() {
  const AudioContextClass = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextClass) {
    return null;
  }

  if (!robotAudioContext) {
    robotAudioContext = new AudioContextClass();
  }
  return robotAudioContext;
}

function addRobotTone(context, frequency, start, duration, type = "sine") {
  const oscillator = context.createOscillator();
  const gain = context.createGain();

  oscillator.type = type;
  oscillator.frequency.setValueAtTime(frequency, start);
  oscillator.frequency.exponentialRampToValueAtTime(frequency * 1.16, start + duration);
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(0.018, start + 0.025);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
  oscillator.connect(gain);
  gain.connect(context.destination);
  oscillator.start(start);
  oscillator.stop(start + duration + 0.02);
}

function playRobotChime() {
  if (!audioEnabled) {
    return;
  }

  const context = ensureAudioContext();
  if (!context || context.state !== "running") {
    return;
  }

  const now = context.currentTime;
  const base = [330, 392, 440][Math.floor(Math.random() * 3)];
  addRobotTone(context, base, now, 0.13, "square");
  addRobotTone(context, base * 1.5, now + 0.14, 0.11, "sine");
}

function playRobotButtonClick() {
  if (!audioEnabled) {
    return;
  }

  const context = ensureAudioContext();
  if (!context || context.state !== "running") {
    return;
  }

  addRobotTone(context, 620, context.currentTime, 0.055, "square");
}

function scheduleAmbientSound() {
  window.clearTimeout(ambientSoundTimer);
  if (!audioEnabled) {
    return;
  }

  const delay = 8000 + Math.random() * 6000;
  ambientSoundTimer = window.setTimeout(() => {
    playRobotChime();
    scheduleAmbientSound();
  }, delay);
}

async function startRobotAudio(playNow = false) {
  if (!audioEnabled) {
    return;
  }

  const context = ensureAudioContext();
  if (!context) {
    return;
  }

  try {
    await context.resume();
  } catch {
    return;
  }

  if (playNow) {
    playRobotChime();
  }
  scheduleAmbientSound();
}

function stopRobotAudio() {
  window.clearTimeout(ambientSoundTimer);
  ambientSoundTimer = null;
  if (robotAudioContext?.state === "running") {
    robotAudioContext.suspend().catch(() => {});
  }
}

function setAudioEnabled(enabled) {
  audioEnabled = enabled;
  try {
    localStorage.setItem(AUDIO_PREFERENCE_KEY, String(enabled));
  } catch {
    // The sound control still works for the current page.
  }

  updateAudioButton();
  if (enabled) {
    startRobotAudio(true);
  } else {
    stopRobotAudio();
  }
}

function armStoredAudioPreference() {
  if (!audioEnabled) {
    return;
  }

  const resume = () => {
    document.removeEventListener("pointerdown", resume);
    document.removeEventListener("keydown", resume);
    startRobotAudio();
  };

  document.addEventListener("pointerdown", resume, { once: true });
  document.addEventListener("keydown", resume, { once: true });
}

document.addEventListener("click", (event) => {
  if (!(event.target instanceof Element)) {
    return;
  }
  const control = event.target.closest("button, a.button, a.nav-pill");
  if (control && !control.classList.contains("sound-toggle")) {
    playRobotButtonClick();
  }
});

document.addEventListener("visibilitychange", () => {
  if (document.hidden) {
    window.clearTimeout(ambientSoundTimer);
    return;
  }
  if (audioEnabled) {
    startRobotAudio();
  }
});

// The little PyBot companion: a small animated PyBot in the corner of every
// page. It reacts to answers, runs and finished pages, and does small friendly
// things while the learner reads. Learners can drag it anywhere; it remembers
// the spot. Hidden on phones, where it would cover the lesson.
const BUDDY_PREFERENCE_KEY = "pybot.buddy.enabled";
const BUDDY_POSITION_KEY = "pybot.buddy.position";
const buddyScreenQuery = window.matchMedia("(min-width: 761px) and (min-height: 481px)");
const reducedMotionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
const BUDDY_TIP_COUNT = 16;
const BUDDY_MARGIN = 14;
// After this long without the learner moving or typing, PyBot takes a nap.
const BUDDY_NAP_AFTER_MS = 75_000;
// Idle antics: a mood, a body move, optional floating particles, and whether
// PyBot may say something (a tip, or its own line).
const BUDDY_IDLE_ANTICS = [
  { mood: "happy", move: "wave" },
  { mood: "wink", move: "hop" },
  { mood: "curious", move: "look", tip: true },
  { mood: "counting", move: "", tip: true },
  { mood: "starry", move: "spin", particles: "✦" },
  { mood: "thinking", move: "", tip: true },
  { mood: "deciding", move: "look" },
  { mood: "welcoming", move: "wave", tip: true },
  { mood: "proud", move: "dance", particles: "♪", say: "buddy.sing" },
  { mood: "happy", move: "blink", tip: true },
  { mood: "surprised", move: "peek" },
  { mood: "happy", move: "stretch", say: "buddy.stretch" },
  { mood: "welcoming", move: "hop", particles: "♥" },
  { mood: "focused", move: "scan", say: "buddy.scan" },
  { mood: "celebrating", move: "flip" },
  { mood: "wink", move: "wiggle", tip: true },
];
let buddyToggle = null;
let buddy = null;
let buddyEnabled = true;
let buddyIdleTimer = null;
let buddyRestTimer = null;
let buddyBubbleTimer = null;
let buddyBusyUntil = 0;
let buddyBubbleUntil = 0;
let buddyHovered = false;
let buddyAsleep = false;
let buddyLastInput = Date.now();
let buddyPosition = null;
let buddyLookFrame = 0;

function storedBuddyPreference() {
  try {
    return localStorage.getItem(BUDDY_PREFERENCE_KEY) !== "false";
  } catch {
    return true;
  }
}

// The spot is kept as fractions of the free space, so it survives resizing.
function storedBuddyPosition() {
  try {
    const [x, y] = (localStorage.getItem(BUDDY_POSITION_KEY) ?? "").split(",").map(Number);
    if (x >= 0 && x <= 1 && y >= 0 && y <= 1) {
      return { x, y };
    }
  } catch {
    // PyBot starts in the corner when storage is unavailable.
  }
  return { x: 1, y: 1 };
}

function buddyFreeSpace() {
  return {
    width: Math.max(0, window.innerWidth - buddy.offsetWidth - BUDDY_MARGIN * 2),
    height: Math.max(0, window.innerHeight - buddy.offsetHeight - BUDDY_MARGIN * 2),
  };
}

function placeBuddy(left, top) {
  const space = buddyFreeSpace();
  const x = Math.min(Math.max(left - BUDDY_MARGIN, 0), space.width);
  const y = Math.min(Math.max(top - BUDDY_MARGIN, 0), space.height);
  buddy.style.left = `${x + BUDDY_MARGIN}px`;
  buddy.style.top = `${y + BUDDY_MARGIN}px`;
  buddyPosition = { x: space.width ? x / space.width : 1, y: space.height ? y / space.height : 1 };
  // Keep the speech bubble on the screen.
  buddy.classList.toggle("bubble-right", x + BUDDY_MARGIN + buddy.offsetWidth / 2 < window.innerWidth / 2);
  buddy.classList.toggle("bubble-below", y + BUDDY_MARGIN < 150);
}

function restoreBuddyPosition() {
  if (!buddy || buddy.hidden) {
    return;
  }
  const space = buddyFreeSpace();
  const position = buddyPosition ?? storedBuddyPosition();
  placeBuddy(BUDDY_MARGIN + position.x * space.width, BUDDY_MARGIN + position.y * space.height);
}

function saveBuddyPosition() {
  try {
    localStorage.setItem(BUDDY_POSITION_KEY, `${buddyPosition.x.toFixed(3)},${buddyPosition.y.toFixed(3)}`);
  } catch {
    // The new spot still works for the current page.
  }
}

function createBuddyToggle() {
  const tools = document.querySelector(".lesson-header-tools, .site-nav");
  if (!tools) {
    return null;
  }

  const button = document.createElement("button");
  button.className = "buddy-toggle";
  button.type = "button";
  button.innerHTML = '<span class="buddy-toggle-icon" aria-hidden="true"></span><span class="buddy-toggle-label"></span>';
  tools.insertBefore(button, tools.querySelector(".language-switch"));
  button.addEventListener("click", () => setBuddyEnabled(!buddyEnabled));
  return button;
}

function updateBuddyButton() {
  if (!buddyToggle) {
    return;
  }

  buddyToggle.classList.toggle("is-on", buddyEnabled);
  buddyToggle.setAttribute("aria-pressed", String(buddyEnabled));
  buddyToggle.setAttribute("aria-label", textFor(buddyEnabled ? "buddy.turnOff" : "buddy.turnOn"));
  buddyToggle.querySelector(".buddy-toggle-label").textContent = textFor(buddyEnabled ? "buddy.on" : "buddy.off");
  buddy?.querySelector(".buddy-hide")?.setAttribute("aria-label", textFor("buddy.hide"));
}

function createBuddy() {
  const element = document.createElement("div");
  element.className = "pybot-buddy";
  element.hidden = true;
  element.innerHTML = `
    <p class="buddy-bubble" aria-hidden="true"></p>
    <button class="buddy-hide" type="button">×</button>
    <div class="buddy-body" aria-hidden="true">
      <div class="pybot-wrap" data-mood="welcoming">
        <div class="pybot">
          <div class="antenna"><span></span></div>
          <div class="ear ear-left"></div>
          <div class="ear ear-right"></div>
          <div class="bot-head">
            <div class="bot-screen">
              <div class="brow brow-left"></div>
              <div class="brow brow-right"></div>
              <div class="eye eye-left"><span></span></div>
              <div class="eye eye-right"><span></span></div>
              <div class="cheek cheek-left"></div>
              <div class="cheek cheek-right"></div>
              <div class="mouth"></div>
            </div>
          </div>
          <div class="bot-neck"></div>
          <div class="arm arm-left"><span class="hand"></span></div>
          <div class="arm arm-right"><span class="hand"></span></div>
          <div class="bot-body">
            <div class="chest-light"></div>
            <span class="chest-code">&lt;/&gt;</span>
          </div>
        </div>
      </div>
    </div>`;
  element.querySelector(".buddy-hide").addEventListener("click", () => {
    setBuddyEnabled(false);
    buddyToggle?.focus();
  });
  element.addEventListener("pointerenter", () => {
    buddyHovered = true;
    window.clearTimeout(buddyBubbleTimer);
  });
  element.addEventListener("pointerleave", () => {
    buddyHovered = false;
    buddyHideBubbleLater(Math.max(1800, buddyBubbleUntil - Date.now()));
  });
  armBuddyDrag(element.querySelector(".buddy-body"));
  document.body.append(element);
  return element;
}

// Dragging moves PyBot; a tap without moving pokes it.
function armBuddyDrag(handle) {
  let drag = null;

  handle.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) {
      return;
    }
    const box = buddy.getBoundingClientRect();
    drag = {
      id: event.pointerId, startX: event.clientX, startY: event.clientY, dx: event.clientX - box.left, dy: event.clientY - box.top,
      moved: false, lastX: event.clientX, lastY: event.clientY, dirX: 0, dirY: 0, turns: [], shook: false,
    };
    handle.setPointerCapture(event.pointerId);
  });

  handle.addEventListener("pointermove", (event) => {
    if (!drag || event.pointerId !== drag.id) {
      return;
    }
    if (!drag.moved && Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) < 6) {
      return;
    }
    if (!drag.moved) {
      drag.moved = true;
      buddyWake(false);
      buddy.classList.add("is-dragging");
      buddyAct("surprised", "", textFor("buddy.dragging"), 60_000);
    }
    placeBuddy(event.clientX - drag.dx, event.clientY - drag.dy);
    noteBuddyShake(drag, event.clientX, event.clientY);
  });

  const end = (event) => {
    if (!drag || event.pointerId !== drag.id) {
      return;
    }
    const { moved, shook } = drag;
    drag = null;
    buddy.classList.remove("is-dragging", "is-shaking");
    if (moved) {
      saveBuddyPosition();
      if (shook) {
        buddyAct("happy", "dizzy", buddyPick("buddy.dizzy", 3), 3800);
        buddyParticles("★", 5);
        return;
      }
      buddyAct("happy", "hop", buddyPick("buddy.dropped", 3), 2400);
    } else if (event.type === "pointerup") {
      buddyPoke();
    }
  };
  handle.addEventListener("pointerup", end);
  handle.addEventListener("pointercancel", end);
}

// Quick back-and-forth while dragging counts as shaking, and makes PyBot dizzy.
function noteBuddyShake(drag, x, y) {
  const now = Date.now();
  [["X", x - drag.lastX], ["Y", y - drag.lastY]].forEach(([axis, delta]) => {
    if (Math.abs(delta) < 4) {
      return;
    }
    const direction = Math.sign(delta);
    if (drag[`dir${axis}`] && direction !== drag[`dir${axis}`]) {
      drag.turns.push(now);
    }
    drag[`dir${axis}`] = direction;
  });
  drag.lastX = x;
  drag.lastY = y;
  drag.turns = drag.turns.filter((time) => now - time < 1200);

  const shaking = drag.turns.length >= 5;
  buddy.classList.toggle("is-shaking", shaking);
  if (shaking && !drag.shook) {
    drag.shook = true;
    buddyShowBubble(textFor("buddy.shaking"));
  }
}

function buddyActive() {
  return Boolean(buddy) && buddyEnabled && buddyScreenQuery.matches && !document.hidden;
}

// Long messages stay longer, so there is time to read them.
function buddyReadingTime(text) {
  return Math.min(13_000, Math.max(4000, 1800 + text.length * 80));
}

function buddyHideBubbleLater(delay) {
  window.clearTimeout(buddyBubbleTimer);
  if (buddyHovered) {
    return;
  }
  buddyBubbleTimer = window.setTimeout(() => buddy?.querySelector(".buddy-bubble")?.classList.remove("is-visible"), delay);
}

function buddyShowBubble(text) {
  const bubble = buddy?.querySelector(".buddy-bubble");
  if (!bubble) {
    return;
  }

  const duration = buddyReadingTime(text);
  bubble.textContent = text;
  bubble.classList.remove("is-visible");
  void bubble.offsetWidth;
  bubble.classList.add("is-visible");
  buddyBubbleUntil = Date.now() + duration;
  buddyHideBubbleLater(duration);
}

function buddyParticles(symbol, count = 5) {
  if (!buddy || reducedMotionQuery.matches) {
    return;
  }
  for (let index = 0; index < count; index += 1) {
    const particle = document.createElement("span");
    particle.className = "buddy-particle";
    particle.textContent = symbol;
    particle.style.setProperty("--particle-x", `${Math.round((Math.random() - 0.5) * 90)}px`);
    particle.style.setProperty("--particle-delay", `${index * 140}ms`);
    buddy.append(particle);
    window.setTimeout(() => particle.remove(), 1800 + index * 140);
  }
}

// Sets a mood and a move for a while, then PyBot goes back to resting.
function buddyAct(mood, move = "", text = "", duration = 2600) {
  if (!buddyActive()) {
    return;
  }

  const wrap = buddy.querySelector(".pybot-wrap");
  wrap.dataset.mood = mood;
  buddy.dataset.move = "";
  void buddy.offsetWidth;
  buddy.dataset.move = move;
  if (text) {
    buddyShowBubble(text);
  }

  // Wait until the learner had time to read before the next antic.
  buddyBusyUntil = Date.now() + Math.max(duration, text ? buddyReadingTime(text) : 0);
  window.clearTimeout(buddyRestTimer);
  buddyRestTimer = window.setTimeout(() => {
    wrap.dataset.mood = "happy";
    buddy.dataset.move = "";
  }, duration);
  scheduleBuddyIdle();
}

function buddyPick(prefix, count) {
  return textFor(`${prefix}${1 + Math.floor(Math.random() * count)}`);
}

function buddyPoke() {
  if (buddyAsleep) {
    buddyWake();
    return;
  }
  if (Math.random() < 0.5) {
    buddyAct("wink", "wiggle", buddyPick("buddy.poke", 3), 2200);
    buddyParticles("♥", 3);
    return;
  }
  buddyIdleAntic(true);
}

function buddyIdleAntic(poked = false) {
  if (!buddyActive() || buddyAsleep || (!poked && Date.now() < buddyBusyUntil)) {
    scheduleBuddyIdle();
    return;
  }

  if (!poked && Date.now() - buddyLastInput > BUDDY_NAP_AFTER_MS) {
    buddySleep();
    return;
  }

  const antic = BUDDY_IDLE_ANTICS[Math.floor(Math.random() * BUDDY_IDLE_ANTICS.length)];
  let text = "";
  if (antic.say) {
    text = textFor(antic.say);
  } else if (antic.tip && (poked || Math.random() < 0.6)) {
    text = buddyPick("buddy.tip", BUDDY_TIP_COUNT);
  }
  buddyAct(antic.mood, antic.move, text, 2400);
  if (antic.particles) {
    buddyParticles(antic.particles);
  }
}

function buddySleep() {
  buddyAsleep = true;
  buddy.querySelector(".pybot-wrap").dataset.mood = "happy";
  buddy.dataset.move = "sleep";
  buddy.querySelector(".buddy-bubble").classList.remove("is-visible");
  buddyParticles("z", 3);
  window.clearTimeout(buddyIdleTimer);
  // Little snores while napping.
  buddyIdleTimer = window.setInterval(() => buddyParticles("z", 3), 4000);
}

function buddyWake(greet = true) {
  if (!buddyAsleep) {
    return;
  }
  buddyAsleep = false;
  window.clearInterval(buddyIdleTimer);
  buddy.dataset.move = "";
  if (greet) {
    buddyAct("surprised", "hop", textFor("buddy.wake"), 2400);
  } else {
    scheduleBuddyIdle();
  }
}

function scheduleBuddyIdle() {
  if (buddyAsleep) {
    return;
  }
  window.clearTimeout(buddyIdleTimer);
  if (!buddyActive()) {
    return;
  }

  // Calmer when the learner prefers less motion.
  const delay = (reducedMotionQuery.matches ? 22000 : 9000) + Math.random() * 8000;
  buddyIdleTimer = window.setTimeout(buddyIdleAntic, delay);
}

// PyBot's eyes follow the pointer.
function buddyLookAt(clientX, clientY) {
  if (!buddyActive() || buddy.hidden || buddyLookFrame) {
    return;
  }
  buddyLookFrame = window.requestAnimationFrame(() => {
    buddyLookFrame = 0;
    const box = buddy.querySelector(".buddy-body").getBoundingClientRect();
    const dx = clientX - (box.left + box.width / 2);
    const dy = clientY - (box.top + box.height * 0.3);
    const distance = Math.hypot(dx, dy) || 1;
    const reach = Math.min(1, distance / 160);
    buddy.style.setProperty("--look-x", `${((dx / distance) * 11 * reach).toFixed(1)}px`);
    buddy.style.setProperty("--look-y", `${((dy / distance) * 8 * reach).toFixed(1)}px`);
  });
}

function noteBuddyInput(event) {
  buddyLastInput = Date.now();
  // A tap on PyBot itself wakes it through the poke.
  if (buddyAsleep && buddyActive() && !buddy.contains(event.target)) {
    buddyWake();
  }
}

// Called from the places that already tell the learner how they did.
function buddyReact(event, activity = null) {
  if (!buddyActive()) {
    return;
  }
  buddyWake(false);

  if (event === "correct") {
    const pageDone = stepActivities.length > 0 && [...stepActivities].every((item) => item.classList.contains("is-complete"));
    if (pageDone) {
      buddyAct("celebrating", "dance", learnerName ? textWithName("buddy.pageDoneNamed") : textFor("buddy.pageDone"), 4200);
      buddyParticles("✦", 8);
      return;
    }
    const text = learnerName && Math.random() < 0.3 ? textWithName("buddy.correctNamed") : buddyPick("buddy.correct", 4);
    const mood = ["celebrating", "starry", "proud"][Math.floor(Math.random() * 3)];
    buddyAct(mood, activity?.classList.contains("fix-activity") ? "spin" : "hop", text, 3000);
    buddyParticles("✦", 4);
  } else if (event === "wrong") {
    buddyAct("encouraging", "nod", buddyPick("buddy.wrong", 4), 3000);
  } else if (event === "running") {
    buddyAct("focused", "", textFor("buddy.running"), 2200);
  } else if (event === "runOk") {
    buddyAct("proud", "hop", textFor("buddy.runOk"), 2800);
  } else if (event === "runError") {
    buddyAct("curious", "look", textFor("buddy.runError"), 3200);
  } else if (event === "nameSaved") {
    buddyAct("welcoming", "wave", textWithName("buddy.nameSaved"), 3200);
    buddyParticles("♥", 4);
  }
}

function syncBuddy() {
  if (!buddy) {
    return;
  }

  const visible = buddyEnabled && buddyScreenQuery.matches;
  buddy.hidden = !visible;
  if (!visible || document.hidden) {
    window.clearTimeout(buddyIdleTimer);
    window.clearInterval(buddyIdleTimer);
    window.clearTimeout(buddyRestTimer);
    buddyAsleep = false;
    return;
  }
  restoreBuddyPosition();
  scheduleBuddyIdle();
}

function setBuddyEnabled(enabled) {
  buddyEnabled = enabled;
  try {
    localStorage.setItem(BUDDY_PREFERENCE_KEY, String(enabled));
  } catch {
    // The companion control still works for the current page.
  }

  updateBuddyButton();
  syncBuddy();
  if (enabled) {
    buddyAct("welcoming", "wave", learnerName ? textWithName("buddy.helloNamed") : textFor("buddy.hello"), 2800);
  }
}

function startBuddy() {
  buddyEnabled = storedBuddyPreference();
  buddyToggle = createBuddyToggle();
  buddy = createBuddy();
  updateBuddyButton();
  syncBuddy();
  buddyScreenQuery.addEventListener("change", syncBuddy);
  document.addEventListener("visibilitychange", syncBuddy);
  window.addEventListener("resize", restoreBuddyPosition);
  document.addEventListener("pointermove", (event) => {
    noteBuddyInput(event);
    buddyLookAt(event.clientX, event.clientY);
  }, { passive: true });
  ["keydown", "scroll", "pointerdown"].forEach((type) => document.addEventListener(type, noteBuddyInput, { passive: true }));
  // Say hello once per visit, not on every page.
  let greeted = false;
  try {
    greeted = sessionStorage.getItem("pybot.buddy.greeted") === "true";
    sessionStorage.setItem("pybot.buddy.greeted", "true");
  } catch {
    // Without storage PyBot greets on every page.
  }
  if (!greeted) {
    window.setTimeout(() => buddyAct("welcoming", "wave", learnerName ? textWithName("buddy.helloNamed") : textFor("buddy.hello"), 3000), 900);
  }
}

function currentMood() {
  return pybotWrap?.dataset.mood ?? "happy";
}

function setMood(mood) {
  const keys = moodKeys[mood];

  if (!keys || !pybotWrap || !pybot || !message) {
    return;
  }

  pybotWrap.dataset.mood = mood;
  pybot.setAttribute("aria-label", textFor(keys.label));
  message.textContent = learnerName ? textWithName(keys.namedMessage) : textFor(keys.message);

  moodButtons.forEach((button) => {
    const isActive = button.dataset.mood === mood;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });
}

function setLanguage(language, persist = true) {
  if (!translations[language]) {
    language = "en";
  }

  currentLanguage = language;
  document.documentElement.lang = language;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const text = textFor(element.dataset.i18n);
    element.textContent = element.dataset.i18nCount ? text.replaceAll("{count}", element.dataset.i18nCount) : text;
  });

  document.querySelectorAll("[data-i18n-aria-label]").forEach((element) => {
    element.setAttribute("aria-label", textFor(element.dataset.i18nAriaLabel));
  });

  document.querySelectorAll("[data-i18n-content]").forEach((element) => {
    element.setAttribute("content", textFor(element.dataset.i18nContent));
  });

  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    element.setAttribute("placeholder", textFor(element.dataset.i18nPlaceholder));
  });

  document.querySelectorAll(".activity-options").forEach((element) => {
    element.setAttribute("role", "group");
    if (!element.dataset.i18nAriaLabel) {
      element.setAttribute("aria-label", textFor("topic.chooseAnswer"));
    }
  });

  labelPatternRows();

  document.querySelectorAll("[data-fix-code-key]").forEach((editor) => {
    if (editor.dataset.edited !== "true") {
      editor.value = textFor(editor.dataset.fixCodeKey);
    }
  });

  document.querySelectorAll("[data-answers-key], [data-fix-answers-key]").forEach((box) => {
    if (box.dataset.edited !== "true") {
      box.value = textFor(box.dataset.answersKey || box.dataset.fixAnswersKey);
    }
  });

  if (pythonEditor && pythonEditor.dataset.edited !== "true") {
    pythonEditor.value = textFor(pythonEditor.dataset.codeKey || "preview.defaultCode");
  }

  const page = document.body.dataset.page || "home";
  document.title = textFor(`meta.${page}Title`);

  languageButtons.forEach((button) => {
    const isActive = button.dataset.language === language;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });

  updateAudioButton();
  updateBuddyButton();

  if (lastPythonError) {
    const { errorType, error, output } = lastPythonError;
    showPythonError(errorType, error, output);
  }

  setMood(currentMood());
  renderPersonalizedMessages();
  updateLearnerNamePanel(
    learnerNameForm
      ? !learnerName || (learnerNamePanel?.dataset.ready === "true" && !learnerNameForm.hidden)
      : false,
  );
  updateCoursePath();
  renderLessonLock();
  renderSelfCheck();
  renderReviewNote();

  if (persist) {
    try {
      localStorage.setItem("pybot.language", language);
    } catch {
      // The language still changes when browser storage is unavailable.
    }
  }
}

function storedLanguage() {
  try {
    const language = localStorage.getItem("pybot.language");
    return translations[language] ? language : "en";
  } catch {
    return "en";
  }
}

function activityStorageKey(activityId) {
  return `pybot.activity.${activityId}`;
}

// The backup allowlist mirrors the storage registry in README.md.
function backupValidators() {
  const validators = {
    "pybot.language": (value) => Boolean(translations[value]),
    "pybot.audio.enabled": (value) => value === "true" || value === "false",
    "pybot.buddy.enabled": (value) => value === "true" || value === "false",
    [LEARNER_NAME_KEY]: (value) => value.length > 0 && normalizeLearnerName(value) === value,
    [PATH_CURRENT_KEY]: (value) => pathSteps.some((step) => step.id === value),
    [PATH_VISITED_KEY]: (value) => value.split(",").every((id) => pathSteps.some((step) => step.id === id)),
    [PATH_DONE_KEY]: (value) => value === "" || value.split(",").every((id) => pathSteps.some((step) => step.id === id)),
    [PATH_KNOWN_KEY]: (value) => value === "" || value.split(",").every((id) => pathSteps.some((step) => step.id === id)),
    [SELF_CHECK_KEY]: (value) => value === "" || value.split(",").every((pair) => {
      const [id, rating] = pair.split(":");
      return pathSteps.some((step) => step.id === id) && SELF_CHECK_RATINGS.includes(rating);
    }),
  };

  activityIds.forEach((activityId) => {
    validators[activityStorageKey(activityId)] = (value) => value === "complete" || value === "review";
  });

  return validators;
}

function renameProgressStep(progress, from, to) {
  const rename = (id) => (id === from ? to : id);
  if (progress[PATH_CURRENT_KEY] === from) {
    progress[PATH_CURRENT_KEY] = to;
  }
  PATH_LIST_KEYS.filter((key) => typeof progress[key] === "string").forEach((key) => {
    progress[key] = progress[key].split(",").map(rename).join(",");
  });
  if (typeof progress[SELF_CHECK_KEY] === "string") {
    progress[SELF_CHECK_KEY] = progress[SELF_CHECK_KEY]
      .split(",")
      .map((pair) => pair.split(":"))
      .map(([id, rating]) => `${rename(id)}:${rating}`)
      .join(",");
  }
}

function renameProgressActivity(progress, from, to) {
  const fromKey = activityStorageKey(from);
  if (Object.hasOwn(progress, fromKey)) {
    progress[activityStorageKey(to)] ??= progress[fromKey];
    delete progress[fromKey];
  }
}

// Runs every migration after `fromVersion`, then drops steps and activities the
// current course no longer has, so progress from any older version still loads.
function upgradeProgress(progress, fromVersion) {
  const upgraded = { ...progress };
  if (fromVersion >= PROGRESS_VERSION) {
    return upgraded;
  }

  for (let version = fromVersion + 1; version <= PROGRESS_VERSION; version += 1) {
    progressMigrations[version]?.(upgraded);
  }

  const isStep = (id) => pathSteps.some((step) => step.id === id);
  const keepIds = (key, isKept) => {
    if (typeof upgraded[key] === "string") {
      upgraded[key] = upgraded[key].split(",").filter(isKept).join(",");
    }
  };
  PATH_LIST_KEYS.forEach((key) => keepIds(key, isStep));
  keepIds(SELF_CHECK_KEY, (pair) => isStep(pair.split(":")[0]));
  if (upgraded[PATH_VISITED_KEY] === "") {
    delete upgraded[PATH_VISITED_KEY];
  }
  if (Object.hasOwn(upgraded, PATH_CURRENT_KEY) && !isStep(upgraded[PATH_CURRENT_KEY])) {
    delete upgraded[PATH_CURRENT_KEY];
  }
  Object.keys(upgraded)
    .filter((key) => key.startsWith(activityStorageKey("")) && !activityIds.includes(key.slice(activityStorageKey("").length)))
    .forEach((key) => delete upgraded[key]);

  return upgraded;
}

// Brings the progress in this browser up to PROGRESS_VERSION after the course changes.
// Progress saved before versions existed counts as version 1.
function upgradeStoredProgress() {
  try {
    const stored = Number.parseInt(localStorage.getItem(PROGRESS_VERSION_KEY) ?? "1", 10);
    const fromVersion = Number.isInteger(stored) && stored > 0 ? stored : 1;
    if (fromVersion > PROGRESS_VERSION) {
      return;
    }

    if (fromVersion < PROGRESS_VERSION) {
      const progress = {};
      for (let index = 0; index < localStorage.length; index += 1) {
        const key = localStorage.key(index);
        if (key?.startsWith("pybot.") && key !== PROGRESS_VERSION_KEY) {
          progress[key] = localStorage.getItem(key);
        }
      }

      const upgraded = upgradeProgress(progress, fromVersion);
      Object.keys(progress).filter((key) => !Object.hasOwn(upgraded, key)).forEach((key) => localStorage.removeItem(key));
      Object.entries(upgraded).forEach(([key, value]) => localStorage.setItem(key, value));
    }

    localStorage.setItem(PROGRESS_VERSION_KEY, String(PROGRESS_VERSION));
  } catch {
    // Storage failure must never block a lesson.
  }
}

function createBackup() {
  const progress = {};

  Object.entries(backupValidators()).forEach(([key, isValid]) => {
    const value = localStorage.getItem(key);
    if (value !== null && isValid(value)) {
      progress[key] = value;
    }
  });

  return {
    format: BACKUP_FORMAT,
    schemaVersion: BACKUP_SCHEMA_VERSION,
    progressVersion: PROGRESS_VERSION,
    exportedAt: new Date().toISOString(),
    progress,
  };
}

// Returns the validated progress entries, or an error key when the file must be rejected.
function readBackup(text) {
  let backup;
  try {
    backup = JSON.parse(text);
  } catch {
    return { error: "backup.invalid" };
  }

  if (!backup || typeof backup !== "object" || backup.format !== BACKUP_FORMAT) {
    return { error: "backup.invalid" };
  }

  // Backups saved before progress versions existed belong to version 1.
  const progressVersion = backup.progressVersion ?? 1;
  if (
    (Number.isInteger(backup.schemaVersion) && backup.schemaVersion > BACKUP_SCHEMA_VERSION) ||
    (Number.isInteger(progressVersion) && progressVersion > PROGRESS_VERSION)
  ) {
    return { error: "backup.newer" };
  }

  const { progress } = backup;
  if (
    backup.schemaVersion !== BACKUP_SCHEMA_VERSION ||
    !Number.isInteger(progressVersion) ||
    progressVersion < 1 ||
    !progress ||
    typeof progress !== "object" ||
    Array.isArray(progress) ||
    !Object.values(progress).every((value) => typeof value === "string")
  ) {
    return { error: "backup.invalid" };
  }

  const validators = backupValidators();
  const entries = Object.entries(upgradeProgress(progress, progressVersion));
  const allValid = entries.every(([key, value]) => Object.hasOwn(validators, key) && validators[key](value));

  return allValid ? { entries, upgraded: progressVersion < PROGRESS_VERSION } : { error: "backup.invalid" };
}

function replaceProgress(entries) {
  const previous = Object.keys(backupValidators()).map((key) => [key, localStorage.getItem(key)]);

  try {
    previous.forEach(([key]) => localStorage.removeItem(key));
    entries.forEach(([key, value]) => localStorage.setItem(key, value));
  } catch (error) {
    previous.forEach(([key, value]) => {
      try {
        if (value === null) {
          localStorage.removeItem(key);
        } else {
          localStorage.setItem(key, value);
        }
      } catch {
        // Restoring the earlier progress is best effort.
      }
    });
    throw error;
  }
}

function setBackupStatus(key, element = backupStatus) {
  if (!element) {
    return;
  }

  if (!key) {
    delete element.dataset.i18n;
    element.textContent = "";
    return;
  }

  element.dataset.i18n = key;
  element.textContent = textFor(key);
}

// Returns false when the browser could not build the backup file.
function downloadBackup() {
  let backup;
  try {
    backup = createBackup();
  } catch {
    return false;
  }

  const file = new Blob([`${JSON.stringify(backup, null, 2)}\n`], { type: "application/json" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(file);
  link.download = `pybot-backup-${backup.exportedAt.slice(0, 10)}.json`;
  document.body.append(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  return true;
}

// Keeps the preferences and the name, and drops every other registered key.
function progressAfterReset() {
  return RESET_KEPT_KEYS.map((key) => [key, localStorage.getItem(key)]).filter(([, value]) => value !== null);
}

function updatePlanProgressSummary() {
  if (!planProgressSummary) {
    return;
  }

  const completed = Array.from(stepActivities).filter((activity) => activity.classList.contains("is-complete")).length;
  const review = Array.from(stepActivities).filter(
    (activity) => !activity.classList.contains("is-complete") && activity.classList.contains("needs-review"),
  ).length;
  const remaining = stepActivities.length - completed - review;

  planProgressSummary.querySelector("[data-progress-complete]").textContent = String(completed);
  planProgressSummary.querySelector("[data-progress-remaining]").textContent = String(remaining);
  planProgressSummary.querySelector("[data-progress-review]").textContent = String(review);
  updateNewActivitiesNote();
  renderSelfCheck();
}

// On a page the learner had finished, say that new activities are waiting.
function updateNewActivitiesNote() {
  const step = pathSteps.find((candidate) => candidate.page === document.body.dataset.page);
  const showNote = Boolean(step) && doneSteps().includes(step.id) && !isStepFinished(step);
  let note = document.querySelector("[data-new-activities-note]");

  if (!showNote) {
    note?.remove();
    return;
  }

  if (!note) {
    note = document.createElement("p");
    note.className = "new-activities-note";
    note.dataset.newActivitiesNote = "";
    note.dataset.i18n = "progress.newActivities";
    note.setAttribute("role", "status");
    planProgressSummary.before(note);
  }
  note.textContent = textFor("progress.newActivities");
}

// Pit stop self-check: the learner rates each zone. Zones rated "review" are
// linked here and marked TO REVIEW on the path map. Zones of challenges that
// are still in review get a gentle note, but the learner decides.
function renderSelfCheck() {
  const section = document.querySelector("[data-selfcheck]");
  if (!section) {
    return;
  }

  const ratings = storedSelfCheck();
  const tricky = new Set();
  document.querySelectorAll("[data-checkpoint-zones]").forEach((challenge) => {
    if (challenge.classList.contains("needs-review") && !challenge.classList.contains("is-complete")) {
      challenge.dataset.checkpointZones.split(",").forEach((id) => tricky.add(id));
    }
  });

  const rows = [...section.querySelectorAll("[data-selfcheck-zone]")];
  rows.forEach((row) => {
    const id = row.dataset.selfcheckZone;
    const group = row.querySelector(".selfcheck-options");
    row.querySelector("[data-selfcheck-noticed]").hidden = !tricky.has(id);
    group.setAttribute("aria-label", textFor("checkpoint.rateLabel").replace("{name}", textFor(group.dataset.selfcheckLabel)));
    row.querySelectorAll("[data-rating]").forEach((button) => {
      button.setAttribute("aria-pressed", String(ratings[id] === button.dataset.rating));
    });
  });

  const answered = rows.filter((row) => ratings[row.dataset.selfcheckZone]);
  const toReview = answered.filter((row) => ratings[row.dataset.selfcheckZone] === "review");
  const result = section.querySelector("[data-selfcheck-result]");
  const links = result.querySelector("[data-selfcheck-links]");
  result.hidden = answered.length === 0;
  result.classList.toggle("is-review", toReview.length > 0);
  result.querySelector("[data-selfcheck-message]").textContent = textFor(
    toReview.length > 0 ? "checkpoint.resultReview"
      : answered.length === rows.length ? section.dataset.selfcheckGoodKey || "checkpoint.resultGood"
      : "checkpoint.resultPending",
  );
  links.replaceChildren(...toReview.map((row) => {
    const zoneLink = row.querySelector(".selfcheck-zone a");
    const item = document.createElement("li");
    const link = document.createElement("a");
    link.href = zoneLink.getAttribute("href");
    link.textContent = textFor("checkpoint.goTo").replace("{name}", zoneLink.textContent);
    item.append(link);
    return item;
  }));
}

document.querySelector("[data-selfcheck]")?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-rating]");
  if (!button) {
    return;
  }
  const ratings = storedSelfCheck();
  ratings[button.closest("[data-selfcheck-zone]").dataset.selfcheckZone] = button.dataset.rating;
  saveSelfCheck(ratings);
  renderSelfCheck();
});

// On a zone the learner chose to review at a pit stop, say so and let them
// mark it as reviewed.
function renderReviewNote() {
  const step = pathSteps.find((candidate) => candidate.page === document.body.dataset.page);
  const showNote = Boolean(step) && storedSelfCheck()[step.id] === "review";
  let note = document.querySelector("[data-review-note]");

  if (!showNote) {
    note?.remove();
    return;
  }

  if (!note) {
    note = document.createElement("div");
    note.className = "review-note";
    note.dataset.reviewNote = "";
    note.setAttribute("role", "status");
    note.append(document.createElement("p"), document.createElement("button"));
    note.querySelector("button").type = "button";
    note.querySelector("button").addEventListener("click", () => {
      const ratings = storedSelfCheck();
      ratings[step.id] = "okay";
      saveSelfCheck(ratings);
      playRobotChime();
      renderReviewNote();
    });
    document.querySelector(".lesson-main .lesson-back")?.after(note);
  }
  note.querySelector("p").textContent = textFor("review.note");
  note.querySelector("button").textContent = textFor("review.done");
}

function showActivityFeedback(activity, result) {
  const activityId = activity.dataset.activityId;
  const feedback = activity.querySelector(".activity-feedback");
  const specificKey = `thinking.${activityId}${result === "success" ? "Success" : "Hint"}`;
  const genericPrefix = activity.classList.contains("fix-activity")
    ? "fix"
    : document.body.dataset.page === "thinking" ? "thinking" : "activity";
  const genericKey = `${genericPrefix}.${result === "success" ? "success" : "hint"}`;
  const key = translations[currentLanguage][specificKey] ? specificKey : genericKey;

  if (!feedback) {
    return;
  }

  feedback.dataset.i18n = key;
  feedback.textContent = textFor(key);
}

function launchAnswerConfetti(activity) {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    return;
  }

  activity.querySelector(".answer-confetti")?.remove();

  const burst = document.createElement("span");
  const colors = ["#ff7a45", "#2764d8", "#ffd84d", "#7199ed", "#ff8d5f"];
  burst.className = "answer-confetti";
  burst.setAttribute("aria-hidden", "true");

  for (let index = 0; index < 30; index += 1) {
    const piece = document.createElement("i");
    const direction = Math.random() < 0.5 ? -1 : 1;
    const distance = 45 + Math.random() * 230;
    piece.className = "confetti-piece";
    piece.style.setProperty("--confetti-x", `${direction * distance}px`);
    piece.style.setProperty("--confetti-rise", `${-75 - Math.random() * 150}px`);
    piece.style.setProperty("--confetti-fall", `${55 + Math.random() * 165}px`);
    piece.style.setProperty("--confetti-rotate", `${360 + Math.random() * 720}deg`);
    piece.style.setProperty("--confetti-delay", `${Math.random() * 110}ms`);
    piece.style.setProperty("--confetti-color", colors[index % colors.length]);
    piece.style.setProperty("--confetti-width", `${6 + Math.random() * 7}px`);
    piece.style.setProperty("--confetti-height", `${8 + Math.random() * 9}px`);
    burst.appendChild(piece);
  }

  activity.appendChild(burst);
  window.setTimeout(() => burst.remove(), 1400);
}

function completeActivity(activity, correctButton, persist = true) {
  const buttons = activity.querySelectorAll(".activity-options button");
  const missingStep = activity.querySelector(".missing-step p");

  activity.classList.add("is-complete");
  activity.classList.remove("needs-review");
  buttons.forEach((button) => {
    const isCorrect = button === correctButton;
    button.classList.toggle("is-correct", isCorrect);
    button.classList.remove("is-wrong");
    button.setAttribute("aria-pressed", String(isCorrect));
    button.disabled = true;
  });

  if (missingStep && correctButton?.dataset.i18n) {
    missingStep.dataset.i18n = correctButton.dataset.i18n;
    missingStep.textContent = textFor(correctButton.dataset.i18n);
  }

  showActivityFeedback(activity, "success");

  if (persist) {
    launchAnswerConfetti(activity);
    buddyReact("correct", activity);
    try {
      localStorage.setItem(activityStorageKey(activity.dataset.activityId), "complete");
    } catch {
      // The activity still works when browser storage is unavailable.
    }
    saveDoneSteps();
  }

  updatePlanProgressSummary();
}

stepActivities.forEach((activity) => {
  const buttons = activity.querySelectorAll(".activity-options button");

  buttons.forEach((button) => {
    button.setAttribute("aria-pressed", "false");
    button.addEventListener("click", () => {
      if (button.dataset.correct === "true") {
        completeActivity(activity, button);
        return;
      }

      buttons.forEach((option) => option.classList.remove("is-wrong"));
      void button.offsetWidth;
      button.classList.add("is-wrong");
      activity.classList.add("needs-review");
      showActivityFeedback(activity, "hint");
      buddyReact("wrong");
      try {
        localStorage.setItem(activityStorageKey(activity.dataset.activityId), "review");
      } catch {
        // The review counter still works for the current page.
      }
      updatePlanProgressSummary();
    });
  });
});

// Answers for input(), one per line, from a box under the code.
function answerLines(element) {
  const text = (element?.value ?? element?.textContent ?? "").replace(/\r\n/g, "\n").replace(/\n+$/, "");
  return text === "" ? [] : text.split("\n");
}

// Turtle drawings come from pybot-turtle.py as JSON: a background color and
// commands (lines, fills, dots, text) in the turtle's world, where (0, 0) is
// the middle, y grows upward, and the visible area is 400 by 400 steps.
const TURTLE_WORLD_SIZE = 400;
const turtleAnimations = new WeakMap();
let turtleColorContext = null;

function turtleColor(color) {
  turtleColorContext ??= document.createElement("canvas").getContext("2d");
  turtleColorContext.fillStyle = "#000000";
  turtleColorContext.fillStyle = String(color);
  return turtleColorContext.fillStyle;
}

function paintTurtleDrawing(canvas, drawing, lastStep = Infinity) {
  const size = Math.round((canvas.clientWidth || 320) * (window.devicePixelRatio || 1));
  if (canvas.width !== size) {
    canvas.width = size;
    canvas.height = size;
  }
  const context = canvas.getContext("2d");
  const scale = size / TURTLE_WORLD_SIZE;
  const x = (value) => (value + TURTLE_WORLD_SIZE / 2) * scale;
  const y = (value) => (TURTLE_WORLD_SIZE / 2 - value) * scale;

  context.fillStyle = turtleColor(drawing?.bg ?? "white");
  context.fillRect(0, 0, size, size);
  if (!drawing) {
    return;
  }

  context.lineCap = "round";
  context.lineJoin = "round";
  drawing.commands.filter((command) => command.step <= lastStep).forEach((command) => {
    context.strokeStyle = context.fillStyle = turtleColor(command.c);
    if (command.t === "line") {
      context.lineWidth = Math.max(2 * (window.devicePixelRatio || 1), command.w * scale);
      context.beginPath();
      context.moveTo(x(command.x1), y(command.y1));
      context.lineTo(x(command.x2), y(command.y2));
      context.stroke();
    } else if (command.t === "fill") {
      context.beginPath();
      command.points.forEach(([px, py], index) => context[index ? "lineTo" : "moveTo"](x(px), y(py)));
      context.closePath();
      context.fill();
    } else if (command.t === "dot") {
      context.beginPath();
      context.arc(x(command.x), y(command.y), (command.size / 2) * scale, 0, Math.PI * 2);
      context.fill();
    } else if (command.t === "text") {
      context.font = `${Math.max(8, command.size) * 1.4 * scale}px "Trebuchet MS", sans-serif`;
      context.textAlign = ["left", "center", "right"].includes(command.align) ? command.align : "left";
      context.fillText(command.text, x(command.x), y(command.y));
    }
  });

  if (lastStep === Infinity) {
    (drawing.turtles ?? []).forEach((turtle) => paintTurtleCursor(context, x(turtle.x), y(turtle.y), turtle.h, scale));
  }
}

// A small arrow, like Python's classic turtle shape, pointing where the turtle faces.
function paintTurtleCursor(context, px, py, heading, scale) {
  context.save();
  context.translate(px, py);
  context.rotate((-heading * Math.PI) / 180);
  context.beginPath();
  context.moveTo(9 * scale, 0);
  context.lineTo(-6 * scale, 6 * scale);
  context.lineTo(-3 * scale, 0);
  context.lineTo(-6 * scale, -6 * scale);
  context.closePath();
  context.fillStyle = "#2764d8";
  context.strokeStyle = "#173b82";
  context.lineWidth = 1.5 * scale;
  context.fill();
  context.stroke();
  context.restore();
}

// Shows a drawing (JSON text, an object, or null for an empty page). When
// animate is true, the lines appear in order, unless the learner prefers
// reduced motion.
function showTurtleDrawing(canvas, drawing, animate = false) {
  const parsed = typeof drawing === "string" ? JSON.parse(drawing) : drawing;
  cancelAnimationFrame(turtleAnimations.get(canvas));
  canvas.classList.toggle("has-drawing", Boolean(parsed));
  const lastStep = Math.max(0, ...(parsed?.commands ?? []).map((command) => command.step));
  const reducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
  if (!parsed || !animate || reducedMotion || lastStep === 0) {
    paintTurtleDrawing(canvas, parsed);
    return;
  }

  const duration = Math.min(2400, lastStep * 40);
  const start = performance.now();
  const frame = (now) => {
    const progress = Math.min(1, (now - start) / duration);
    paintTurtleDrawing(canvas, parsed, progress < 1 ? Math.ceil(progress * lastStep) : Infinity);
    if (progress < 1) {
      turtleAnimations.set(canvas, requestAnimationFrame(frame));
    }
  };
  turtleAnimations.set(canvas, requestAnimationFrame(frame));
}

// Two drawings match when they leave the same marks on the page, whatever the
// order: a line drawn in two pieces counts the same as one long line.
function turtleDrawingMarks(drawing) {
  const round = (value) => Math.round(value * 2) / 2;
  const marks = [`bg ${turtleColor(drawing.bg)}`];
  const lines = new Map();

  drawing.commands.forEach((command) => {
    const color = turtleColor(command.c);
    if (command.t === "line") {
      const dx = command.x2 - command.x1;
      const dy = command.y2 - command.y1;
      const length = Math.hypot(dx, dy);
      if (length < 0.5) {
        return;
      }
      let angle = (Math.atan2(dy, dx) * 180) / Math.PI;
      angle = ((angle % 180) + 180) % 180;
      if (angle > 179.75) {
        angle -= 180;
      }
      const radians = (angle * Math.PI) / 180;
      const ux = Math.cos(radians);
      const uy = Math.sin(radians);
      const offset = command.x1 * -uy + command.y1 * ux;
      const a = command.x1 * ux + command.y1 * uy;
      const b = command.x2 * ux + command.y2 * uy;
      const key = `line ${color} ${command.w} ${round(angle)} ${round(offset)}`;
      lines.set(key, [...(lines.get(key) ?? []), [Math.min(a, b), Math.max(a, b)]]);
    } else if (command.t === "fill") {
      const points = command.points.map(([px, py]) => `${round(px)},${round(py)}`);
      marks.push(`fill ${color} ${[...new Set(points)].sort().join(" ")}`);
    } else if (command.t === "dot") {
      marks.push(`dot ${color} ${round(command.x)} ${round(command.y)} ${round(command.size)}`);
    } else if (command.t === "text") {
      marks.push(`text ${color} ${round(command.x)} ${round(command.y)} ${command.text}`);
    }
  });

  lines.forEach((spans, key) => {
    spans.sort((first, second) => first[0] - second[0]);
    const merged = [];
    spans.forEach(([from, to]) => {
      const last = merged.at(-1);
      if (last && from <= last[1] + 1) {
        last[1] = Math.max(last[1], to);
      } else {
        merged.push([from, to]);
      }
    });
    merged.forEach(([from, to]) => marks.push(`${key} ${round(from)} ${round(to)}`));
  });

  return [...new Set(marks)].sort();
}

function sameTurtleDrawing(goal, drawing) {
  const goalMarks = turtleDrawingMarks(goal);
  const marks = turtleDrawingMarks(drawing);
  return goalMarks.length === marks.length && goalMarks.every((mark, index) => mark === marks[index]);
}

document.querySelectorAll("[data-turtle-goal-canvas]").forEach((canvas) => {
  showTurtleDrawing(canvas, canvas.closest("[data-turtle-goal]").dataset.turtleGoal);
});
document.querySelectorAll("[data-turtle-canvas], [data-fix-turtle]").forEach((canvas) => showTurtleDrawing(canvas, null));

// "Fix PyBot's code": the learner edits a broken snippet and runs it until the
// output matches the goal. Runs share the page's Python worker; their ids are
// negative so they never clash with the main runner's ids.
function endFixRuns(result) {
  const pending = [...fixRuns.values()];
  fixRuns.clear();
  pending.forEach((finish) => finish(result));
}

function runFixCode(code, answers = []) {
  return new Promise((resolve) => {
    fixRunId -= 1;
    const id = fixRunId;
    const timer = window.setTimeout(() => {
      // A loop that never ends: restart the worker so Python is usable again.
      fixRuns.delete(id);
      stopPythonWorker();
      resolve({ type: "timeout" });
    }, FIX_RUN_TIMEOUT_MS);
    fixRuns.set(id, (result) => {
      window.clearTimeout(timer);
      resolve(result);
    });
    pythonWorker ??= createPythonWorker();
    pythonWorker.postMessage({ id, code, answers });
  });
}

// Compare outputs line by line, ignoring spaces at the ends of lines.
function normalizedOutput(text) {
  return text.replace(/\r\n/g, "\n").split("\n").map((line) => line.trimEnd()).join("\n").trim();
}

function fixGoalMatches(activity, output) {
  const key = activity.dataset.fixExpectedKey;
  // Accept either language's goal, so switching language after editing still works.
  return Object.values(translations).some((texts) => texts[key] && normalizedOutput(texts[key]) === normalizedOutput(output));
}

function resetFixActivity(activity) {
  const editor = activity.querySelector("[data-fix-code-key]");
  if (!editor) {
    return;
  }
  editor.value = textFor(editor.dataset.fixCodeKey);
  delete editor.dataset.edited;
  const answers = activity.querySelector("[data-fix-answers-key]");
  if (answers) {
    answers.value = textFor(answers.dataset.fixAnswersKey);
    delete answers.dataset.edited;
  }
  const drawing = activity.querySelector("[data-fix-turtle]");
  if (drawing) {
    showTurtleDrawing(drawing, null);
  }
  activity.querySelector("[data-fix-output]").textContent = "";
}

// A turtle activity is solved when the drawing matches the goal drawing, and
// the printed output matches too when the activity also has a goal output.
function fixActivitySolved(activity, result) {
  const turtleGoal = activity.dataset.turtleGoal;
  if (turtleGoal && (!result.drawing || !sameTurtleDrawing(JSON.parse(turtleGoal), JSON.parse(result.drawing)))) {
    return false;
  }
  return !activity.dataset.fixExpectedKey || fixGoalMatches(activity, result.output);
}

document.querySelectorAll(".fix-activity").forEach((activity) => {
  const editor = activity.querySelector("[data-fix-code-key]");
  const output = activity.querySelector("[data-fix-output]");
  const runButton = activity.querySelector("[data-fix-run]");
  const answers = activity.querySelector("[data-fix-answers-key], [data-fix-answers]");
  const drawing = activity.querySelector("[data-fix-turtle]");

  editor.addEventListener("input", () => {
    editor.dataset.edited = "true";
  });

  answers?.addEventListener("input", () => {
    answers.dataset.edited = "true";
  });

  activity.querySelector("[data-fix-restart]").addEventListener("click", () => resetFixActivity(activity));

  runButton.addEventListener("click", async () => {
    if (window.location.protocol === "file:") {
      output.textContent = textFor("preview.serveHint");
      return;
    }

    runButton.disabled = true;
    output.textContent = textFor("preview.loading");
    let result;
    try {
      result = await runFixCode(editor.value, answerLines(answers));
    } catch (error) {
      result = { type: "error", error: error instanceof Error ? error.message : String(error) };
      pythonWorker = null;
    }
    runButton.disabled = false;

    if (result.type === "stopped" || result.type === "timeout") {
      output.textContent = textFor(result.type === "timeout" ? "fix.timeout" : "preview.stopped");
      return;
    }

    if (drawing) {
      showTurtleDrawing(drawing, result.drawing, true);
    }

    if (result.type === "error") {
      const details = [result.output, result.error].filter(Boolean).join("\n").trim();
      output.textContent = `${pythonErrorHint(result.errorType, result.error ?? "")}\n\n${details}`;
    } else {
      output.textContent = result.output.trim() || textFor(result.drawing ? "turtle.drawn" : "preview.noOutput");
      if (fixActivitySolved(activity, result)) {
        playRobotChime();
        completeActivity(activity, null);
        return;
      }
    }

    if (!activity.classList.contains("is-complete")) {
      activity.classList.add("needs-review");
      showActivityFeedback(activity, "hint");
      buddyReact("wrong");
      try {
        localStorage.setItem(activityStorageKey(activity.dataset.activityId), "review");
      } catch {
        // The review counter still works for the current page.
      }
      updatePlanProgressSummary();
    }
  });
});

// "Fix the pattern": tapping a shape turns it into the next shape. The activity
// is complete when the row matches the goal pattern.
const PATTERN_SHAPES = ["circle", "square", "triangle", "star"];

function labelPatternRows() {
  document.querySelectorAll("[data-pattern-row]").forEach((row) => {
    [...row.children].forEach((button, index) => {
      button.setAttribute("aria-label", textFor("shape.position")
        .replace("{n}", index + 1)
        .replace("{shape}", textFor(`shape.${button.dataset.shape}`)));
    });
  });
}

function renderPatternRow(activity, shapes) {
  const row = activity.querySelector("[data-pattern-row]");
  const goal = activity.dataset.patternGoal.split(",");

  row.replaceChildren(...shapes.map((shape, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pattern-shape";
    button.dataset.shape = shape;
    button.innerHTML = `<span class="shape shape-${shape}" aria-hidden="true"></span>`;
    button.disabled = activity.classList.contains("is-complete");
    button.addEventListener("click", () => {
      const next = [...shapes];
      next[index] = PATTERN_SHAPES[(PATTERN_SHAPES.indexOf(shape) + 1) % PATTERN_SHAPES.length];
      if (next.join(",") === goal.join(",")) {
        playRobotChime();
        completeActivity(activity, null);
      } else if (shape === goal[index]) {
        // The learner changed a shape that already fit.
        showActivityFeedback(activity, "hint");
      }
      renderPatternRow(activity, next);
      row.children[index].focus();
    });
    return button;
  }));
  labelPatternRows();
}

function resetPatternActivity(activity) {
  if (activity.dataset.patternStart) {
    renderPatternRow(activity, activity.dataset.patternStart.split(","));
  }
}

document.querySelectorAll(".pattern-fix").forEach(resetPatternActivity);

// "Put the steps in order": drag a step up or down (or select it and use the
// arrow keys), then check. The activity is complete when every step is in order.
function orderItems(activity) {
  return [...activity.querySelectorAll(".order-list > li")];
}

function numberOrderItems(activity) {
  orderItems(activity).forEach((item, index) => {
    item.querySelector("span").textContent = String(index + 1);
  });
}

function setOrderItems(activity, order) {
  const list = activity.querySelector(".order-list");
  const items = orderItems(activity);
  order.forEach((position) => list.appendChild(items.find((item) => item.dataset.order === position)));
  numberOrderItems(activity);
}

function finishOrderActivity(activity) {
  setOrderItems(activity, orderItems(activity).map((item) => item.dataset.order).sort((a, b) => a - b));
  orderItems(activity).forEach((item) => item.removeAttribute("tabindex"));
  activity.querySelector(".order-check").disabled = true;
}

function resetOrderActivity(activity) {
  if (!activity.classList.contains("order-activity")) {
    return;
  }
  setOrderItems(activity, activity.dataset.orderStart.split(","));
  orderItems(activity).forEach((item) => item.setAttribute("tabindex", "0"));
  activity.querySelector(".order-check").disabled = false;
}

function checkOrderActivity(activity) {
  const order = orderItems(activity).map((item) => Number(item.dataset.order));
  if (order.every((position, index) => position === index + 1)) {
    playRobotChime();
    finishOrderActivity(activity);
    completeActivity(activity, null);
    return;
  }

  const check = activity.querySelector(".order-check");
  check.classList.remove("is-wrong");
  void check.offsetWidth;
  check.classList.add("is-wrong");
  activity.classList.add("needs-review");
  showActivityFeedback(activity, "hint");
  buddyReact("wrong");
  try {
    localStorage.setItem(activityStorageKey(activity.dataset.activityId), "review");
  } catch {
    // The review counter still works for the current page.
  }
  updatePlanProgressSummary();
}

document.querySelectorAll(".order-activity").forEach((activity) => {
  const list = activity.querySelector(".order-list");
  const feedback = activity.querySelector(".activity-feedback");
  activity.dataset.orderStart = orderItems(activity).map((item) => item.dataset.order).join(",");

  orderItems(activity).forEach((item) => {
    let grabOffset = 0;

    const followPointer = (event) => {
      const others = orderItems(activity).filter((other) => other !== item);
      const before = others.find((other) => {
        const box = other.getBoundingClientRect();
        return event.clientY < box.top + box.height / 2;
      });
      if ((before ?? null) !== item.nextElementSibling) {
        list.insertBefore(item, before ?? null);
        numberOrderItems(activity);
      }
      item.style.transform = "";
      const shift = event.clientY - grabOffset - item.getBoundingClientRect().top;
      item.style.transform = `translateY(${shift}px)`;
    };

    const drop = () => {
      item.classList.remove("is-dragging");
      item.style.transform = "";
      item.removeEventListener("pointermove", followPointer);
    };

    item.addEventListener("pointerdown", (event) => {
      if (activity.classList.contains("is-complete") || event.button > 0) {
        return;
      }
      event.preventDefault();
      item.focus({ preventScroll: true });
      grabOffset = event.clientY - item.getBoundingClientRect().top;
      item.setPointerCapture(event.pointerId);
      item.classList.add("is-dragging");
      item.addEventListener("pointermove", followPointer);
    });
    item.addEventListener("pointerup", drop);
    item.addEventListener("pointercancel", drop);

    item.addEventListener("keydown", (event) => {
      if (activity.classList.contains("is-complete") || !["ArrowUp", "ArrowDown"].includes(event.key)) {
        return;
      }
      event.preventDefault();
      const target = event.key === "ArrowUp" ? item.previousElementSibling : item.nextElementSibling?.nextElementSibling ?? null;
      if (event.key === "ArrowUp" && !target) {
        return;
      }
      if (event.key === "ArrowDown" && !item.nextElementSibling) {
        return;
      }
      list.insertBefore(item, target);
      numberOrderItems(activity);
      item.focus();
      feedback.removeAttribute("data-i18n");
      feedback.textContent = textFor("thinking.orderMoved")
        .replace("{step}", item.querySelector("p").textContent)
        .replace("{n}", orderItems(activity).indexOf(item) + 1);
    });
  });

  activity.querySelector(".order-check").addEventListener("click", () => checkOrderActivity(activity));
});

// "Code hunt": tap every object that has code inside. A wrong tap asks for a
// review; finding them all completes the activity.
function huntItems(activity) {
  return activity.querySelectorAll(".hunt-item");
}

function updateHuntCount(activity) {
  const found = activity.querySelectorAll('.hunt-item[data-hunt="code"].is-found').length;
  const counter = activity.querySelector("[data-hunt-found]");
  if (counter) {
    counter.textContent = String(found);
  }
  return found;
}

function finishCodeHunt(activity) {
  huntItems(activity).forEach((item) => {
    item.classList.toggle("is-found", item.dataset.hunt === "code");
    item.classList.remove("is-wrong");
    item.setAttribute("aria-pressed", String(item.dataset.hunt === "code"));
    item.disabled = true;
  });
  updateHuntCount(activity);
}

function resetCodeHunt(activity) {
  if (!activity.classList.contains("code-hunt")) {
    return;
  }
  huntItems(activity).forEach((item) => {
    item.classList.remove("is-found", "is-wrong");
    item.setAttribute("aria-pressed", "false");
    item.disabled = false;
  });
  updateHuntCount(activity);
}

document.querySelectorAll(".code-hunt").forEach((activity) => {
  const total = activity.querySelectorAll('.hunt-item[data-hunt="code"]').length;
  huntItems(activity).forEach((item) => {
    item.addEventListener("click", () => {
      if (item.dataset.hunt === "code") {
        item.classList.add("is-found");
        item.setAttribute("aria-pressed", "true");
        item.disabled = true;
        if (updateHuntCount(activity) === total) {
          finishCodeHunt(activity);
          completeActivity(activity, null);
        }
        return;
      }

      item.classList.remove("is-wrong");
      void item.offsetWidth;
      item.classList.add("is-wrong");
      activity.classList.add("needs-review");
      showActivityFeedback(activity, "hint");
      buddyReact("wrong");
      try {
        localStorage.setItem(activityStorageKey(activity.dataset.activityId), "review");
      } catch {
        // The review counter still works for the current page.
      }
      updatePlanProgressSummary();
    });
  });
});

function restoreStepActivities() {
  stepActivities.forEach((activity) => {
    let storedState;
    try {
      storedState = localStorage.getItem(activityStorageKey(activity.dataset.activityId));
    } catch {
      return;
    }

    if (storedState === "complete") {
      const correctButton = activity.querySelector('[data-correct="true"]');
      if (correctButton || activity.classList.contains("fix-activity")) {
        completeActivity(activity, correctButton, false);
      } else if (activity.classList.contains("pattern-fix")) {
        completeActivity(activity, null, false);
        renderPatternRow(activity, activity.dataset.patternGoal.split(","));
      } else if (activity.classList.contains("code-hunt")) {
        completeActivity(activity, null, false);
        finishCodeHunt(activity);
      } else if (activity.classList.contains("order-activity")) {
        completeActivity(activity, null, false);
        finishOrderActivity(activity);
      }
    } else if (storedState === "review") {
      activity.classList.add("needs-review");
      showActivityFeedback(activity, "hint");
    }
  });

  updatePlanProgressSummary();
}

function resetStepActivity(activity) {
  const buttons = activity.querySelectorAll(".activity-options button");
  const missingStep = activity.querySelector(".missing-step p");
  const feedback = activity.querySelector(".activity-feedback");

  activity.classList.remove("is-complete", "needs-review");
  activity.querySelector(".answer-confetti")?.remove();
  resetFixActivity(activity);
  resetPatternActivity(activity);
  resetCodeHunt(activity);
  resetOrderActivity(activity);
  buttons.forEach((button) => {
    button.disabled = false;
    button.classList.remove("is-correct", "is-wrong");
    button.setAttribute("aria-pressed", "false");
  });

  if (missingStep) {
    missingStep.removeAttribute("data-i18n");
    missingStep.textContent = "?";
  }

  if (feedback) {
    feedback.removeAttribute("data-i18n");
    feedback.textContent = "";
  }

  try {
    localStorage.removeItem(activityStorageKey(activity.dataset.activityId));
  } catch {
    // The visible page still resets when browser storage is unavailable.
  }
}

// Shows an in-page question card right after `anchor` and resolves with the
// chosen value, or null when the card is dismissed with Escape.
function askInPage(anchor, { tone = "info", textKey, count, noteKey, choices }) {
  document.querySelectorAll(".inline-ask").forEach((card) => card.cancel?.());

  return new Promise((resolve) => {
    const card = document.createElement("div");
    card.className = `inline-ask inline-ask-tone-${tone}`;
    card.setAttribute("role", "group");

    const icon = document.createElement("span");
    icon.className = "inline-ask-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = tone === "danger" ? "!" : "?";

    const body = document.createElement("div");
    body.className = "inline-ask-body";

    if (noteKey) {
      const note = document.createElement("p");
      note.className = "inline-ask-note";
      note.dataset.i18n = noteKey;
      note.textContent = textFor(noteKey);
      body.append(note);
    }

    const text = document.createElement("p");
    text.className = "inline-ask-text";
    text.id = `inline-ask-${Date.now()}`;
    text.dataset.i18n = textKey;
    if (count !== undefined) {
      text.dataset.i18nCount = String(count);
    }
    text.textContent = textFor(textKey).replaceAll("{count}", String(count ?? ""));
    card.setAttribute("aria-labelledby", text.id);
    body.append(text);

    const actions = document.createElement("div");
    actions.className = "inline-ask-actions";
    body.append(actions);

    const finish = (value) => {
      card.remove();
      anchor.hidden = false;
      anchor.focus();
      resolve(value);
    };
    card.cancel = () => finish(null);

    choices.forEach(({ value, key, style = "secondary" }) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `inline-ask-button inline-ask-${style}`;
      button.dataset.i18n = key;
      button.textContent = textFor(key);
      button.addEventListener("click", () => finish(value));
      actions.append(button);
    });

    card.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        finish(null);
      }
    });

    card.append(icon, body);
    anchor.after(card);
    anchor.hidden = true;
    actions.querySelector("button")?.focus();
  });
}

activityResetButtons.forEach((button) => {
  button.addEventListener("click", async () => {
    const answer = await askInPage(button, {
      tone: "warn",
      textKey: "progress.resetConfirm",
      choices: [
        { value: "clear", key: "progress.resetYes", style: "primary" },
        { value: null, key: "ask.keep" },
      ],
    });
    if (answer !== "clear") {
      return;
    }

    stepActivities.forEach(resetStepActivity);
    forgetDoneStep(document.body.dataset.page);
    updatePlanProgressSummary();
    const status = button.closest(".page-progress-tools")?.querySelector(".progress-reset-status");
    if (status) {
      status.dataset.i18n = "progress.resetDone";
      status.textContent = textFor("progress.resetDone");
    }
  });
});

languageButtons.forEach((button) => {
  button.addEventListener("click", () => setLanguage(button.dataset.language));
});

moodButtons.forEach((button) => {
  button.addEventListener("click", () => setMood(button.dataset.mood));
});

learnerNameForm?.addEventListener("submit", (event) => {
  event.preventDefault();
  const nextName = normalizeLearnerName(learnerNameInput?.value ?? "");
  const error = learnerNameForm.querySelector(".learner-name-error");

  if (!nextName) {
    learnerNameForm.classList.add("is-invalid");
    if (error) {
      error.hidden = false;
    }
    learnerNameInput?.focus();
    return;
  }

  learnerName = nextName;
  try {
    localStorage.setItem(LEARNER_NAME_KEY, learnerName);
  } catch {
    // The chosen name still works for the current page.
  }

  setMood(currentMood());
  renderPersonalizedMessages();
  updateLearnerNamePanel(false);
  learnerNameEdit?.focus();
  playRobotChime();
  buddyReact("nameSaved");
});

learnerNameEdit?.addEventListener("click", () => {
  updateLearnerNamePanel(true);
  learnerNameInput?.focus();
  learnerNameInput?.select();
});

learnerNameForget?.addEventListener("click", () => {
  learnerName = "";
  try {
    localStorage.removeItem(LEARNER_NAME_KEY);
  } catch {
    // The name is still forgotten for the current page.
  }

  setMood(currentMood());
  renderPersonalizedMessages();
  updateLearnerNamePanel(true);
  learnerNameInput?.focus();
});

backupExportButton?.addEventListener("click", () => {
  setBackupStatus(downloadBackup() ? "backup.exported" : "backup.failed");
});

progressResetButton?.addEventListener("click", async () => {
  setBackupStatus("", resetStatus);
  const backupChoice = await askInPage(progressResetButton, {
    tone: "info",
    textKey: "reset.askBackup",
    choices: [
      { value: "backup", key: "reset.saveFirst", style: "primary" },
      { value: "skip", key: "reset.skipBackup" },
      { value: null, key: "ask.cancel", style: "quiet" },
    ],
  });
  if (!backupChoice) {
    setBackupStatus("reset.cancelled", resetStatus);
    return;
  }

  const savedBackup = backupChoice === "backup";
  if (savedBackup && !downloadBackup()) {
    setBackupStatus("backup.failed", resetStatus);
    return;
  }

  const eraseChoice = await askInPage(progressResetButton, {
    tone: "danger",
    noteKey: savedBackup ? "backup.exported" : undefined,
    textKey: "reset.confirm",
    choices: [
      { value: "erase", key: "reset.eraseYes", style: "danger" },
      { value: null, key: "ask.keep" },
    ],
  });
  if (eraseChoice !== "erase") {
    setBackupStatus("reset.cancelled", resetStatus);
    return;
  }

  try {
    replaceProgress(progressAfterReset());
  } catch {
    setBackupStatus("reset.failed", resetStatus);
    return;
  }

  setLanguage(storedLanguage(), false);
  setBackupStatus("reset.done", resetStatus);
});

if (progressVersionLabel) {
  progressVersionLabel.textContent = String(PROGRESS_VERSION);
}

backupImportButton?.addEventListener("click", () => backupImportInput?.click());

backupImportInput?.addEventListener("change", async () => {
  const file = backupImportInput.files?.[0];
  backupImportInput.value = "";
  if (!file) {
    return;
  }

  const result = file.size > BACKUP_MAX_BYTES ? { error: "backup.invalid" } : readBackup(await file.text());
  if (result.error) {
    setBackupStatus(result.error);
    return;
  }

  const finished = result.entries.filter(([, value]) => value === "complete").length;
  setBackupStatus("");
  const answer = await askInPage(backupImportButton, {
    tone: "warn",
    textKey: "backup.confirm",
    count: finished,
    choices: [
      { value: "load", key: "backup.loadYes", style: "primary" },
      { value: null, key: "ask.keep" },
    ],
  });
  if (answer !== "load") {
    setBackupStatus("backup.cancelled");
    return;
  }

  try {
    replaceProgress(result.entries);
  } catch {
    setBackupStatus("backup.failed");
    return;
  }

  const nextAudio = storedAudioPreference();
  learnerName = storedLearnerName();
  setLanguage(storedLanguage(), false);
  updateLearnerNamePanel(!learnerName);
  if (nextAudio !== audioEnabled) {
    setAudioEnabled(nextAudio);
  }
  if (storedBuddyPreference() !== buddyEnabled) {
    setBuddyEnabled(!buddyEnabled);
  }
  setBackupStatus(result.upgraded ? "backup.upgraded" : "backup.imported");
});

pythonEditor?.addEventListener("input", () => {
  pythonEditor.dataset.edited = "true";
});

pythonAnswers?.addEventListener("input", () => {
  pythonAnswers.dataset.edited = "true";
});

pythonRunButton?.addEventListener("click", () => {
  if (!pythonEditor || !pythonOutput) {
    return;
  }

  if (window.location.protocol === "file:") {
    setPythonOutput("preview.serveHint");
    return;
  }

  pythonRunId += 1;
  setPythonRunning(true);
  setPythonOutput("preview.loading");
  buddyReact("running");

  try {
    pythonWorker ??= createPythonWorker();
    pythonWorker.postMessage({ id: pythonRunId, code: pythonEditor.value, answers: answerLines(pythonAnswers) });
  } catch (error) {
    setPythonRunning(false);
    setPythonOutput("preview.error", error instanceof Error ? error.message : String(error));
    pythonWorker = null;
  }
});

pythonStopButton?.addEventListener("click", () => stopPythonWorker());

startAnalytics();
audioEnabled = storedAudioPreference();
learnerName = storedLearnerName();
saveKnownPathSteps();
// A locked page does not count as visited, so it cannot open its own zone.
if (!renderLessonLock()) {
  saveCurrentPathStep();
}
saveDoneSteps();
soundToggle = createSoundToggle();
startBuddy();
createSupportLink();
createFaqLink();
setLanguage(storedLanguage(), false);
updateLearnerNamePanel(!learnerName);
restoreStepActivities();
armStoredAudioPreference();
